$assembly=[Reflection.Assembly]::LoadFrom((Join-Path $ProjectRoot 'bin\x64\Debug\HalconWinFormsDemo.exe'))
function Assert([bool]$condition,[string]$message){if(-not$condition){throw $message}}
function Pump([int]$ms){$frame=New-Object Windows.Threading.DispatcherFrame;$timer=New-Object Windows.Threading.DispatcherTimer;$timer.Interval=[TimeSpan]::FromMilliseconds($ms);$timer.Add_Tick({$timer.Stop();$frame.Continue=$false});$timer.Start();[Windows.Threading.Dispatcher]::PushFrame($frame)}
function Shot([string]$path){$dir=Split-Path -Parent $path;if(-not(Test-Path $dir)){[IO.Directory]::CreateDirectory($dir)|Out-Null};$window.UpdateLayout();$a=$window.PointToScreen([Windows.Point]::new(0,0));$b=$window.PointToScreen([Windows.Point]::new($window.ActualWidth,$window.ActualHeight));$screenW=[Math]::Max(1,[int]($b.X-$a.X));$screenH=[Math]::Max(1,[int]($b.Y-$a.Y));$bitmap=[Drawing.Bitmap]::new($screenW,$screenH);$g=[Drawing.Graphics]::FromImage($bitmap);try{try{$g.CopyFromScreen([int]$a.X,[int]$a.Y,0,0,[Drawing.Size]::new($screenW,$screenH));$bitmap.Save([IO.Path]::GetFullPath($path));return "${screenW}x${screenH}"}catch{}}finally{$g.Dispose();$bitmap.Dispose()};$dpiX=96*$screenW/[Math]::Max(1,$window.ActualWidth);$dpiY=96*$screenH/[Math]::Max(1,$window.ActualHeight);$render=New-Object Windows.Media.Imaging.RenderTargetBitmap($screenW,$screenH,$dpiX,$dpiY,[Windows.Media.PixelFormats]::Pbgra32);$render.Render($window);$encoder=New-Object Windows.Media.Imaging.PngBitmapEncoder;$encoder.Frames.Add([Windows.Media.Imaging.BitmapFrame]::Create($render));$stream=[IO.File]::Open([IO.Path]::GetFullPath($path),[IO.FileMode]::Create);try{$encoder.Save($stream)}finally{$stream.Dispose()};"${screenW}x${screenH} (WPF fallback)"}
function Image([int]$width,[int]$height){[HalconDotNet.HObject]$raw=$null;[HalconDotNet.HOperatorSet]::GenImageConst([ref]$raw,'byte',$width,$height);try{New-Object HalconDotNet.HImage($raw)}finally{$raw.Dispose()}}
function Visuals($root){$items=New-Object Collections.ArrayList;function Walk($node){if($null-eq$node){return};$count=[Windows.Media.VisualTreeHelper]::GetChildrenCount($node);for($i=0;$i-lt$count;$i++){$child=[Windows.Media.VisualTreeHelper]::GetChild($node,$i);[void]$items.Add($child);Walk $child}};Walk $root;$items}
$temp=Join-Path([IO.Path]::GetTempPath())('halcon-vm-s57-ui-'+[Guid]::NewGuid().ToString('N'));[IO.Directory]::CreateDirectory($temp)|Out-Null
$main=$assembly.GetType('HalconWinFormsDemo.MainWindow',$true);$serviceType=$assembly.GetType('HalconWinFormsDemo.Services.RecipeService',$true);$loggerType=$assembly.GetType('HalconWinFormsDemo.Services.AppLogger',$true);$kindType=$assembly.GetType('HalconWinFormsDemo.Models.VmToolKind',$true);$catalogType=$assembly.GetType('HalconWinFormsDemo.Models.VmToolCatalogItem',$true);$private=[Reflection.BindingFlags]'Instance,NonPublic';$all=[Reflection.BindingFlags]'Instance,NonPublic,Public'
$service=$serviceType.GetConstructor([Type[]]@([string])).Invoke([object[]]@($temp.ToString()));$logger=$loggerType.GetConstructor([Type[]]@([string])).Invoke([object[]]@($temp.ToString()));$window=$main.GetConstructor($private,$null,[Type[]]@($serviceType,$loggerType),$null).Invoke([object[]]@($service,$logger))
function F([string]$name){$field=$main.GetField($name,$all);if($null-eq$field){return $null};$value=$field.GetValue($window);Write-Output -NoEnumerate $value}
function Tool([string]$kind,[string]$name){$main.GetMethod('CreateFlowTool',$private).Invoke($window,[object[]]@([Enum]::Parse($kindType,$kind),$name,$true,$null))}
function Run($tool){$main.GetMethod('ExecuteFlowTool',$private).Invoke($window,[object[]]@($tool,'S57 UI'))|Out-Null}
function SelectTool($tool){$raw=$tool.PSObject.BaseObject;$list=F 'FlowToolList';$list.SelectedItems.Clear();$list.SelectedItem=$raw;$main.GetMethod('FlowToolList_SelectionChanged',$private).Invoke($window,[object[]]@($list,$null))|Out-Null;$main.GetMethod('LoadDockConfigurationDraft',$private).Invoke($window,[object[]]@($raw))|Out-Null;(F 'RightTabs').SelectedItem=(F 'DockConfigurationTab');(F 'DockConfigurationTabs').SelectedItem=(F 'DockParametersTaskTab');$main.GetMethod('UpdateRightTaskNavigationState',$private).Invoke($window,[object[]]@('Parameters'))|Out-Null;$main.GetMethod('RefreshUiState',$private).Invoke($window,@())|Out-Null;$main.GetMethod('FitFlowButton_Click',$private).Invoke($window,[object[]]@($null,$null))|Out-Null;$main.GetMethod('ScheduleRefreshDisplay',$private).Invoke($window,@())|Out-Null}
function FocusCatalog(){ $main.GetField('toolCatalogMode',$private).SetValue($window,'All');$item=(F 'toolCatalog')|Where-Object{$_.Kind.ToString()-eq'ResultLogicAggregation'}|Select-Object -First 1;$script:focusedCatalogItem=$item;(F 'ToolSearchTextBox').Text=$item.Name;$main.GetMethod('RefreshToolCatalogView',$private).Invoke($window,@())|Out-Null;$list=F 'ToolCatalogList';$list.SelectedItem=$item;$list.ScrollIntoView($item);$list.UpdateLayout();Pump 180 }
$app=[Windows.Application]::Current;if($null-eq$app){$app=New-Object Windows.Application;$app.ShutdownMode=[Windows.ShutdownMode]::OnExplicitShutdown}
$window.Left=2;$window.Top=2;$window.Width=1938;$window.Height=1158;$window.Topmost=$true;$window.Show();Pump 500
$flow=F 'flowTools';$main.GetMethod('DisposeFlowTools',$private).Invoke($window,@())|Out-Null;$flow.Clear();$source=Tool ImageSource 'Inspection Input';$judgeA=Tool NumericJudge 'Presence Judge';$judgeB=Tool NumericJudge 'Quality Judge';$logic=Tool ResultLogicAggregation 'Final Result Logic';$text=Tool TextAssembly 'Result Message';$judgeA.SetInputBinding('Value',$source.ToolId,'Width');$judgeA.InputToolId=$source.ToolId;$judgeA.InputPortName='Width';$judgeA.NumericLowerLimit=700;$judgeA.NumericUpperLimit=740;$judgeB.SetInputBinding('Value',$source.ToolId,'Height');$judgeB.InputToolId=$source.ToolId;$judgeB.InputPortName='Height';$judgeB.NumericLowerLimit=500;$judgeB.NumericUpperLimit=540;$logic.SetInputBinding('ResultCodeA',$judgeA.ToolId,'ResultCode');$logic.SetInputBinding('ResultCodeB',$judgeB.ToolId,'ResultCode');$logic.Parameters.ResultLogicOperation='AllOk';$text.SetInputBinding('ResultCode',$logic.ToolId,'ResultCode');$text.Parameters.TextAssemblyTemplate='FINAL={ResultCode}';foreach($tool in @($source,$judgeA,$judgeB,$logic,$text)){$flow.Add($tool)}
$source.SetOutputValue('Width',[double]720);$source.SetOutputValue('Height',[double]520);$source.SetOutputValue('ResultCode','OK');$source.ResultCode='OK';Run $judgeA;Run $judgeB;Run $logic;Run $text
$current=Image 720 520;$main.GetField('currentImage',$private).SetValue($window,$current);$main.GetField('currentImagePath',$private).SetValue($window,'S57 result logic');(F 'viewport').SetImageSize(720,520);SelectTool $logic;FocusCatalog;Pump 700
Assert($null-eq(F 'AddToolButton')) 'Permanent add button is still generated';$catalogList=F 'ToolCatalogList';$catalogContainer=$catalogList.ItemContainerGenerator.ContainerFromItem($focusedCatalogItem);Assert($null-ne$catalogContainer) 'Selected catalog row was not realized';$catalogButtons=Visuals $catalogContainer|Where-Object{$_ -is[Windows.Controls.Button]-and$_.Tag-and$catalogType.IsInstanceOfType($_.Tag)};$visibleStars=@($catalogButtons|Where-Object{$_.Opacity-gt0.01});Assert($catalogButtons.Count-eq1)('Favorite action was not realized: '+$catalogButtons.Count);Assert($visibleStars.Count-eq1)('Selected row favorite action is missing or duplicated: '+$visibleStars.Count);$wide=Shot $WideOutputPath
$window.WindowState=[Windows.WindowState]::Normal;$window.MinWidth=0;$window.MinHeight=0;$window.Width=1366;$window.Height=768;$window.Left=2;$window.Top=2;SelectTool $logic;FocusCatalog;Pump 700;Assert((F 'ToolCatalogPanel').ActualWidth-gt0-and(F 'FlowWorkspacePanel').ActualWidth-gt0-and(F 'RightTabs').ActualWidth-gt0) 'Core regions are not simultaneously visible at 1366x768';$compact=Shot $CompactOutputPath
$main.GetField('recipeCloseConfirmed',$private).SetValue($window,$true);$window.Close();$app.Shutdown();if(Test-Path $temp){Remove-Item -LiteralPath $temp -Recurse -Force}
Write-Output "S57_UI_CAPTURE=PASS; Wide=$WideOutputPath; Compact=$CompactOutputPath; WideSize=$wide; CompactSize=$compact; VisibleRowFavoriteActions=$($visibleStars.Count); PermanentAddButton=0"
